async function run() {
  if (!process.env.MONGODB_URI) throw new Error("MONGODB_URI missing");
  await mongoose.connect(process.env.MONGODB_URI, { dbName: "news_website", bufferCommands: false });
  const articlesCol = mongoose.connection.db.collection("articles");

  const lines = gscRawData.split("\n").filter(Boolean).slice(1);
  const urls = lines.map(line => line.split(",")[0].trim());

  console.log(`Checking ${urls.length} URLs from new GSC export...`);

  const results = [];
  let foundCount = 0;
  let missingCount = 0;
  let publishedCount = 0;
  let draftCount = 0;
  let otherCount = 0;

  for (const rawUrl of urls) {
    if (rawUrl === "https://www.novexa.news/") continue;
    if (rawUrl.includes("/category/")) {
      results.push({ url: rawUrl, type: "category", status: "200 (Category Page)" });
      continue;
    }

    const slug = rawUrl.replace("https://www.novexa.news/news/", "").trim();
    
    // Check MongoDB directly
    const doc = await articlesCol.findOne({ slug });
    if (doc) {
      foundCount++;
      if (doc.status === "published") publishedCount++;
      else if (doc.status === "draft") draftCount++;
      else otherCount++;

      const indexable = isArticleIndexable(doc);
      results.push({
        url: rawUrl,
        slug,
        found: true,
        id: doc._id,
        status: doc.status,
        reviewStatus: doc.reviewStatus,
        generationMode: doc.generationMode,
        indexable,
        issues: articleIndexabilityIssues(doc)
      });
    } else {
      // Try searching by partial slug / title match in case of slight slug difference
      const titleSearch = slug.replaceAll("-", " ");
      const partialDoc = await articlesCol.findOne({ $or: [{ slug: { $regex: slug.slice(0, 30), $options: "i" } }, { title: { $regex: titleSearch.slice(0, 30), $options: "i" } }] });
      
      missingCount++;
      results.push({
        url: rawUrl,
        slug,
        found: false,
        partialMatch: partialDoc ? { id: partialDoc._id, slug: partialDoc.slug, status: partialDoc.status } : null
      });
    }
  }

  console.log({
    totalUrls: urls.length,
    foundCount,
    missingCount,
    publishedCount,
    draftCount,
    otherCount
  });

  const missingList = results.filter(r => !r.found);
  const draftList = results.filter(r => r.found && r.status !== "published");

  console.log("\nMissing URLs in DB:", missingList);
  console.log("\nDraft / Unpublished URLs in DB:", draftList);
}

run().catch(console.error).finally(() => mongoose.disconnect());
